<script>
 import HypothesisReview from '../../src/components/defiant/HypothesisReview.svelte';
 let context=$state(0),revision=$state('a'.repeat(64)),count=$state(0),hold=$state(false),pending=$state(false),last=$state('');
 let release=null,timeoutOnce=false;
 const key='invented-hypothesis-fixture';
 function read(){return JSON.parse(sessionStorage.getItem(key)||'null');}
 function save(v){sessionStorage.setItem(key,JSON.stringify(v));return structuredClone(v);}
 async function request(path,options={}){count++;const body=options.body?JSON.parse(options.body):null;last=JSON.stringify({path,body});let record=read();
  if(path==='/hypotheses'&&!body)return {organizationId:'sample_org',items:record?[{hypothesisId:record.hypothesis.hypothesisId,registeredAt:record.hypothesis.registeredAt,question:record.hypothesis.question,mode:record.hypothesis.mode}]:[]};
  if(path==='/hypotheses'&&body){if(hold){pending=true;await new Promise(resolve=>release=resolve);pending=false;}const h={...body,schemaVersion:1,evaluatorVersion:'absolute-source-total-earned-v1',hypothesisId:'b'.repeat(64),organizationId:'sample_org',registeredAt:'2026-10-23T12:00:00.000Z',actorId:'fixture-operator',actorUid:'fixture-uid',baseline:{...body.baseline,amount:'10.25',metric:'source-total-earned',sourceHash:'d'.repeat(64),qualification:'Supplied statement; not profit.'},target:{...body.target,start:body.target.month+'-01T00:00:00.000Z',end:'2026-12-01T00:00:00.000Z'},temporalQualification:'source-availability-unverified'};const saved=save({hypothesis:h,outcome:null,correction:null});if(timeoutOnce){timeoutOnce=false;throw Object.assign(Error('Response timeout'),{status:408});}return saved;}
  if(path.endsWith('/outcome')){const future=record.hypothesis.mode==='future-period-outcome',answer=body.kind==='answer-assertion';record.outcome={kind:body.kind,reference:body.reference,observedAt:body.observedAt,recordedAt:'2026-10-23T12:02:00.000Z',actorId:'fixture-operator',revision:body.reference.revision||'a'.repeat(64),fact:future?null:{amount:'10.25',currency:'USD',metric:'source-total-earned',month:record.hypothesis.target.month,sourceHash:'d'.repeat(64),qualification:'Supplied statement; not profit.'},evaluation:{result:future?'unavailable':'criterion-met',reason:future?'period-not-elapsed':null,meaning:future?'future-business-evaluation-unavailable':answer?'answer-assertion-evidence':'declared-analysis-numeric-rule'},temporalQualification:answer?'retrospective-observation; not-prospective':'registration-before-capture-only',evidenceReuse:'reused-known-evidence',revisionChanged:revision!==record.hypothesis.baseline.revision,sourceHashChanged:false,observation:answer?{observationId:body.reference.observationId,assertionIndex:body.reference.assertionIndex,answerHash:'f'.repeat(64),createdAt:'2026-10-22T00:00:00.000Z',selectedResult:{assertion:{value:'0',currency:'USD',span:{text:'Reported zero'}},amountCheck:'mismatch',currencyCheck:'match',period:'2025-06',periodQualification:'declared-earnings-period',limitation:'Only the declared number is checked.'}}:null};return save(record);}
  if(path.endsWith('/correction')){record.correction={comment:body.comment,actorId:'fixture-operator',actorUid:'fixture-uid',createdAt:'2026-10-23T12:03:00.000Z',qualification:'Attributed comment, not ground truth.'};return save(record);}
  return record;
 }
</script>
<button onclick={()=>timeoutOnce=true}>Timeout next registration response</button><button onclick={()=>revision='c'.repeat(64)}>Change evidence revision</button><button onclick={()=>context++}>Switch fixture account</button><button onclick={()=>hold=true}>Hold next registration</button><button disabled={!pending} onclick={()=>release?.()}>Release held registration</button>
<output aria-label="Hypothesis requests">{count}</output><output aria-label="Last hypothesis request">{last}</output>
{#key context}<HypothesisReview {request} {revision} onEvidence={value=>revision=value.evidenceRevision}/>{/key}
<style>output{display:block;overflow-wrap:anywhere}button{max-width:100%;white-space:normal}</style>
